def transform(grid):
    # Color 2 each 4-cell that shares a row/column with any 9-marker in a pattern
    # where a 9 is one of a pair bounding a run of 4s. In effect line up the 9s;
    # 4s in the intervening span become 2, while 9 markers remain unchanged.
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # In this task, 9s are marker pixels; fill the complementing gaps between
    # 9 markers only when the intervening cells are all 4, changing these to 2.
    for r in range(h):
        marks=[c for c in range(w) if grid[r][c]==9]
        for a,b in zip(marks,marks[1:]):
            for c in range(a+1,b):
                if grid[r][c]==4: out[r][c]=2
    for c in range(w):
        marks=[r for r in range(h) if grid[r][c]==9]
        for a,b in zip(marks,marks[1:]):
            for r in range(a+1,b):
                if grid[r][c]==4: out[r][c]=2
    return out
